{
  "name": "rf_write_reg",
  "confidence": "medium",
  "docstring": "Writes a 32-bit value to an RF register index 0..31 through the bandgap-trimmed indirect MMIO register window, issuing start commands and clearing the access controls after the write.",
  "subsystem": "rf",
  "var_renames": {
    "a1": "reg_idx",
    "a2": "value",
    "v4": "rf_base"
  },
  "struct_hints": [
    {
      "offset": 64,
      "meaning": "access command/busy register, set before the RF write and cleared afterward"
    },
    {
      "offset": 76,
      "meaning": "write command field, programmed to 0x8800 before selecting the register window"
    },
    {
      "offset": 84,
      "meaning": "control register loaded with 0x275 before the write, with bit 0x4 cleared after it"
    },
    {
      "offset": 2048,
      "meaning": "RF register data window base; a reg_idx maps to offset 2048 + 4 * reg_idx"
    }
  ]
}
